"""LiteLLM model wiring (generated by genproj).

The model is built in Python, not in an agent-spec file, because the gateway is
OpenAI-compatible and the spec format cannot express a `base_url`. Keeping this
in one file means a later move to spec-driven model config is a one-file change,
and the decision layer can point at a different gateway alias without
regenerating the project.

`model` is the id AS THE GATEWAY KNOWS IT (its alias), not a provider prefix.
"""

from __future__ import annotations

import os

from pydantic_ai.models.openai import OpenAIChatModel
from pydantic_ai.providers.openai import OpenAIProvider

from agent.headers import HeaderForwardingClient

# The gateway this agent calls for models (and registers with, when
# registration is generated). One value, two uses, so they cannot diverge.
#
# There is no in-code default when no gateway was named at generation time:
# guessing an address is how a service looks wired up while dialing a host that
# does not exist. Supply it in the environment instead.
LITELLM_BASE_URL = os.environ.get("LITELLM_BASE_URL", "http://litellm:4000")
# A virtual key scoped to invoking this agent and calling the models it uses.
LITELLM_API_KEY = os.environ.get("LITELLM_API_KEY", "")
# The model alias as the gateway knows it.
LITELLM_MODEL = os.environ.get("LITELLM_MODEL", "deepseek-v4-flash")


def build_model() -> OpenAIChatModel:
    """The OpenAI-compatible model pointed at the LiteLLM gateway.

    The HTTP client forwards the LiteLLM context headers (trace id, agent id)
    that arrived on the A2A request, so calls back to the gateway are grouped
    into the right trace and attributed to this agent.
    """
    if not LITELLM_BASE_URL:
        raise RuntimeError(
            "LITELLM_BASE_URL is not set. This agent makes its model calls "
            "through the LiteLLM gateway, so the gateway's address must be in "
            "the environment (e.g. injected from Doppler)."
        )
    provider = OpenAIProvider(
        base_url=LITELLM_BASE_URL,
        api_key=LITELLM_API_KEY,
        http_client=HeaderForwardingClient(),
    )
    return OpenAIChatModel(LITELLM_MODEL, provider=provider)
